typedef struct order_service order_service;   /* opaque handle; order_service.h */
int order_service_place(order_service *svc, const order_req *r, order_id *out);
/* order_service.c */
int order_service_place(order_service *svc, const order_req *r, order_id *out) {
    if (db_begin(svc->db) != 0) return -1;             /* service owns the transaction */
    if (orders_insert(svc->db, r, out) != 0) goto rollback;
    if (stock_reserve(svc->db, *out) != 0) goto rollback;
    return db_commit(svc->db);
rollback:
    db_rollback(svc->db);
    return -1;
}
